<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const app = document.getElementById("app");

    const fieldConfigs = [
      {
        id: "full-name",
        name: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true,
        help: "Use the name you'd like support to address you by."
      },
      {
        id: "email-address",
        name: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true,
        help: "We will use this only to reply to your request."
      },
      {
        id: "phone-number",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        help: "Format: +1 555 123 4567, 555-123-4567, or a similar local format."
      }
    ];

    const requiredText = '<span class="required-marker" aria-hidden="true"> *</span>';

    function fieldTemplate(field) {
      const describedBy = `${field.id}-help`;
      return `
        <div class="form-field">
          <label for="${field.id}">
            ${field.label}${field.required ? requiredText : ""}
          </label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            ${field.required ? "required" : ""}
            aria-describedby="${describedBy}"
          >
          <p class="field-help" id="${field.id}-help">${field.help}</p>
          <p class="field-error" id="${field.id}-error" hidden></p>
        </div>
      `;
    }

    function contactFormTemplate() {
      return `
        <main id="main-content">
          <div class="shell">
            <p class="eyebrow">Support</p>
            <h1>Contact our support team</h1>
            <p class="intro">Send us your contact details and we will reach out with help for your request.</p>

            <section class="form-card" aria-label="Contact form">
              <p class="form-note"><span aria-hidden="true">*</span> Required fields</p>
              <p class="status" id="form-status" role="status" aria-live="polite"></p>

              <form id="support-form" novalidate>
                ${fieldConfigs.map(fieldTemplate).join("")}

                <div class="actions">
                  <button type="submit">Send message</button>
                </div>
              </form>
            </section>
          </div>
        </main>
      `;
    }

    app.innerHTML = contactFormTemplate();

    const form = document.getElementById("support-form");
    const status = document.getElementById("form-status");
    const fields = Object.fromEntries(fieldConfigs.map((field) => [
      field.name,
      {
        config: field,
        input: document.getElementById(field.id),
        error: document.getElementById(`${field.id}-error`)
      }
    ]));

    function setFieldState(field, message) {
      const { input, error } = field;
      const helpId = `${input.id}-help`;
      const errorId = `${input.id}-error`;
      const describedBy = [helpId];

      if (message) {
        error.textContent = message;
        error.hidden = false;
        input.setAttribute("aria-invalid", "true");
        describedBy.push(errorId);
      } else {
        error.textContent = "";
        error.hidden = true;
        input.removeAttribute("aria-invalid");
      }

      input.setAttribute("aria-describedby", describedBy.join(" "));
    }

    function isValidPhone(value) {
      const trimmed = value.trim();
      if (!trimmed) {
        return true;
      }

      if (!/^[+\d()\s.-]+$/.test(trimmed)) {
        return false;
      }

      const digits = trimmed.replace(/\D/g, "");
      return digits.length >= 7 && digits.length <= 15;
    }

    function validateField(field, showMessage) {
      const value = field.input.value.trim();
      let message = "";

      if (field.config.required && !value) {
        message = `Error: Enter your ${field.config.label.toLowerCase()}.`;
      } else if (field.config.type === "email" && value && !field.input.checkValidity()) {
        message = "Error: Enter a valid email address, like name@example.com.";
      } else if (field.config.type === "tel" && !isValidPhone(value)) {
        message = "Error: Enter a phone number using digits, spaces, parentheses, dashes, or a leading +.";
      }

      if (showMessage || message) {
        setFieldState(field, message);
      }

      return !message;
    }

    function validateForm() {
      let firstInvalid = null;
      let isValid = true;

      for (const field of Object.values(fields)) {
        const valid = validateField(field, true);
        if (!valid && !firstInvalid) {
          firstInvalid = field.input;
        }
        isValid = isValid && valid;
      }

      if (!isValid && firstInvalid) {
        firstInvalid.focus();
        status.textContent = "Please fix the highlighted fields.";
      }

      return isValid;
    }

    for (const field of Object.values(fields)) {
      field.input.addEventListener("blur", () => validateField(field, true));
      field.input.addEventListener("input", () => {
        if (field.input.hasAttribute("aria-invalid")) {
          validateField(field, true);
        }
      });
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!validateForm()) {
        return;
      }

      status.textContent = "All fields look good and are ready to send.";
    });
  </script>
</body>
